CAT = "cahamRegs"; SEG = "REG"
# RIC-3 Basic syllabus 5.1.1 (Regulations and Policies, topics 1-1 to 1-14, 1-20 to 1-21):
# Radiocommunication Regulations (SOR/96-484) ss 15.3, 42, 44, 46 to 49; Radiocommunication Act
# ss 8, 8.1, 9; RIC-3 Issue 5 (March 2022); RBR-4 Issue 3 (July 2022) ss 2, 3.2, 6, 9, 13 and
# Schedule V; RIC-9 Issue 2 call sign policy. See sources.md.

Q = [
("The Radiocommunication Regulations define the amateur radio service as one used for self-training and technical investigation:",
 "Without pecuniary interest", ["Under a club's supervision", "On non-commercial bands only", "With a paid station licence"],
 "The Regulations define the amateur radio service as self-training, intercommunication or technical investigation by people interested in radio technique solely with a personal aim and without pecuniary interest. Club supervision is not part of the definition."),
("What lets a Basic holder operate an amateur station without a separate radio station licence?",
 "A licence exemption", ["Annual station registration", "RAC membership card", "An IARP Class 2 permit"],
 "Section 15.3 of the Radiocommunication Regulations exempts amateur apparatus from the radio licence requirement when the operator holds a qualifying certificate and follows RBR-4. No yearly station licence is needed."),
("A certificate holder moves to a new mailing address. ISED must be told within:",
 "30 days", ["10 days", "60 days", "90 days"],
 "RBR-4 section 13 requires the holder of an Amateur Radio Operator Certificate to notify ISED's Amateur Radio Service Centre of a change of mailing address within 30 days."),
("Who issues Canadian amateur certificates and call signs nationally?",
 "Amateur Radio Service Centre", ["Radio Amateurs of Canada", "Your accredited examiner", "The provincial spectrum office"],
 "RIC-3 says ISED's Amateur Radio Service Centre in Sault Ste. Marie is responsible nationally for all amateur certification, call signs and examiner accreditation. Examiners mark the exam but do not issue the certificate."),
("Which certificate gives the same amateur privileges as the Basic Qualification?",
 "Radiotelephone General (Maritime)", ["Restricted Operator (Maritime)", "Restricted Operator (Aeronautical)", "Morse Code qualification alone"],
 "RIC-3 section 4.3 and Regulations section 42 list the Radiotelephone Operator's General Certificates (Aeronautical, Maritime and Land) as giving Basic privileges. The restricted operator certificates are not on that list."),
("A Basic certificate issued before April 1, 2002 carries the privileges of:",
 "Basic with Honours", ["Basic without Honours", "Basic and Advanced", "Basic and Morse Code"],
 "RIC-3 section 4.3 grants holders of a Basic Qualification issued before April 1, 2002 the same privileges as Basic with Honours, including the bands below 30 MHz. It does not grant Advanced privileges."),
("With the Basic Qualification only, which transmitters may you build and operate?",
 "Professional commercial kits", ["Any design under 250 W input", "Any design used above 30 MHz", "Home-built units a club checked"],
 "RIC-3 section 4.5.1 limits Basic holders to assembling commercially available transmitter kits of professional design. Home-made transmitters, at any power or frequency, need the Advanced Qualification."),
("Which qualification must you hold to install a home-built RF power amplifier?",
 "Advanced", ["Basic with Honours", "Morse Code (5 wpm)", "Basic"],
 "Section 44 of the Regulations requires the Advanced Qualification to install or operate a transmitter or RF amplifier that is not commercially manufactured. Honours adds HF bands, not building rights."),
("Who may install a repeater that retransmits voice within the same band?",
 "An Advanced holder", ["A Basic with Honours holder", "Any club officer", "A Basic holder with a log"],
 "Section 44(b)(i) of the Regulations requires the Advanced Qualification to install apparatus that receives and automatically retransmits radiotelephone communications within the same band."),
("A Basic holder wants a radio to work on new amateur frequencies. This is allowed only by:",
 "Software reprogramming", ["Clipping an internal jumper", "Changing its crystal", "Fitting a new filter board"],
 "RIC-3 section 4.5.1 lets Basic holders re-program equipment for the amateur bands when it can be done by a computer program. Any physical change to the circuitry, even a jumper, needs the Advanced Qualification."),
("Under RIC-3, which of these is not remote control of a station?",
 "Operating through a repeater", ["Changing power over the Internet", "Switching bands over a radio link", "Setting a fixed rig's mode by phone"],
 "RIC-3 defines remote control as indirectly manipulating a radio's technical parameters through an intermediate medium, which Basic holders may not do. It states that operation through a repeater is not remote control."),
("A friend without a certificate may speak on your amateur station only when:",
 "You supervise in person", ["They give your call sign", "They stay above 30 MHz", "You note their name in the log"],
 "Section 46 of the Regulations lets any person take part in amateur operation under the supervision and in the presence of a qualified operator. Identifying with your call does not replace being there."),
("Which content do the Regulations forbid on amateur stations?",
 "Commercially recorded material", ["Weather reports for a club net", "Simulated emergency traffic", "Messages for a non-amateur friend"],
 "Section 47 bars music, commercially recorded material, broadcast programming and communications supporting business. Simulated emergency messages and personal third-party messages are allowed."),
("Codes and ciphers may be used on amateur stations only if they are:",
 "Not secret", ["Sent below 30 MHz", "Logged with the key", "Used by two Canadians"],
 "Section 47(b) of the Regulations allows an amateur to use a code or cipher that is not secret. Logging the key does not make a secret code legal."),
("Amateurs may not transmit communications in support of:",
 "Business activities", ["Club activities", "Public service events", "School science projects"],
 "Section 47(c)(iv) bars radiocommunications in support of industrial, business or professional activities. Clubs, schools and public service events are personal, non-commercial uses."),
("In a real or simulated emergency, an amateur may communicate only with:",
 "Other amateur stations", ["Any station that replies", "Police and fire stations", "Marine and aircraft stations"],
 "Section 48 of the Regulations limits emergency communication to stations in the amateur radio service, carrying messages for a person, government or relief organization."),
("An amateur relaying messages at a charity run may accept:",
 "No payment at all", ["Payment for fuel only", "A free meal only", "A modest honorarium"],
 "Section 49 of the Regulations requires amateurs to operate without demanding or accepting remuneration in any form for what they transmit or receive. Covering fuel is still a form of payment."),
("You overhear a private radio call. You may share its content with permission from:",
 "Its sender or addressee", ["Any radio inspector", "Your local radio club", "The repeater's owner"],
 "Section 9(2) of the Radiocommunication Act bars intercepting and divulging a radiocommunication except as permitted by its originator or the person it was meant for, or as the Regulations prescribe."),
("Knowingly sending a false distress call is forbidden by the:",
 "Radiocommunication Act", ["RBR-4 standard only", "ITU Radio Regulations only", "RIC-3 circular only"],
 "Section 9(1)(a) of the Radiocommunication Act forbids sending any false or fraudulent distress signal. RIC-3 itself has no status in law."),
("Normally, a radio inspector may enter a private home only with:",
 "Consent or a warrant", ["24 hours' written notice", "A neighbour's complaint", "A peace officer present"],
 "Section 8(2) of the Radiocommunication Act lets an inspector enter a dwelling-house only with the occupant's consent, under a warrant, or in exigent circumstances. Other places may be entered at any reasonable time."),
("A US amateur operating in Ontario by voice identifies with their FCC call plus:",
 "Portable or mobile, and VE3", ["A slash and VE3 only", "VA3 in place of their prefix", "The name of their US state"],
 "RBR-4 section 9 has a US licensee add the word mobile or portable on voice, or an oblique stroke on Morse, and the Canadian prefix for the location from Schedule V, such as VE3 or VA3 in Ontario."),
("A foreign amateur operating in Canada under a reciprocal arrangement has privileges like which Canadian certificate?",
 "Basic and Advanced", ["Basic only", "Basic with Honours", "Basic and Morse Code"],
 "RBR-4 section 3.2 gives an authorized foreign amateur the privileges of a Basic and Advanced holder, but never more than their own licence allows."),
("An IARP Class 2 permit, issued to Basic-only holders, covers which bands abroad?",
 "Bands above 30 MHz", ["All amateur bands", "Bands below 30 MHz", "Bands above 144 MHz"],
 "RIC-3 section 8.2.2 limits the Class 2 International Amateur Radio Permit to amateur allocations above 30 MHz, subject to the visited country's rules. Class 1 needs Morse Code at 12 wpm."),
("Who issues CEPT T/R 61-01 permits to Canadians for the Minister?",
 "Radio Amateurs of Canada", ["ISED district offices", "The Amateur Radio Service Centre", "Global Affairs Canada"],
 "RIC-3 section 8.2.1 says the Minister has delegated Radio Amateurs of/du Canada (RAC) to issue CEPT permits. The applicant needs both Basic and Advanced qualifications."),
("Which call sign prefix is assigned to amateurs in Nova Scotia?",
 "VE1", ["VE9", "VY2", "VO1"],
 "RBR-4 Schedule V lists VE1 and VA1 for Nova Scotia. VE9 is New Brunswick, VY2 Prince Edward Island and VO1 Newfoundland."),
("A call sign beginning with VY0 belongs to an amateur based in:",
 "Nunavut", ["Yukon", "Northwest Territories", "Labrador"],
 "RBR-4 Schedule V assigns VY0 to Nunavut. Yukon is VY1, the Northwest Territories VE8 and Labrador VO2."),
("An amateur with a VE6 call moves from Alberta to Manitoba. What must they do?",
 "Apply for a VE4 or VA4 call", ["Keep VE6 and add /4", "Nothing, calls are national", "Write the Basic exam again"],
 "RIC-9 says an amateur who moves to another prefix area must apply for a call sign with the prefix for the new area. Manitoba is VE4 and VA4 under RBR-4 Schedule V."),
("How long is a deceased amateur's call sign held for an immediate family member to claim?",
 "One year", ["Six months", "Two years", "Five years"],
 "RIC-9 keeps a deceased amateur's call sign off the available list for one year, during which a qualified immediate family member in the same prefix area may apply for it."),
]
